from heapq import heappop, heappush


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    adj = [[] for _ in range(n)]
    for u, v, minutes, energy in roads:
        adj[u].append((v, minutes, energy))

    has_station = [False] * n
    for u in stations:
        has_station[u] = True

    # dist[k][u][b]: minimum minutes to reach u with charge b,
    # having used exactly k swaps.
    inf = float("inf")
    dist = [
        [[inf] * (capacity + 1) for _ in range(n)]
        for _ in range(max_swaps + 1)
    ]
    dist[0][s][capacity] = 0

    # Ordered by minutes first, then swaps.
    heap = [(0, 0, s, capacity)]

    while heap:
        elapsed, used, u, charge = heappop(heap)

        if elapsed != dist[used][u][charge]:
            continue

        if u == t:
            return (elapsed, used)

        # Drive a road.
        for v, minutes, energy in adj[u]:
            if energy > charge:
                continue

            new_charge = min(capacity, charge - energy)
            new_time = elapsed + minutes

            if new_time < dist[used][v][new_charge]:
                dist[used][v][new_charge] = new_time
                heappush(heap, (new_time, used, v, new_charge))

        # Swap, including when the current battery is already full.
        if has_station[u] and used < max_swaps:
            new_used = used + 1
            new_time = elapsed + swap_time

            if new_time < dist[new_used][u][capacity]:
                dist[new_used][u][capacity] = new_time
                heappush(heap, (new_time, new_used, u, capacity))

    return None

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be nonnegative")

    n = len(messages)
    gap_limit = min(max_gap, n)

    # dp[gap][used] is the best score for the processed prefix,
    # with exactly `used` length and `gap` trailing dropped messages.
    # None means that state is unreachable.
    dp = [[None] * (budget + 1)]
    dp[0][0] = 0

    for i, (length, value, pinned) in enumerate(messages):
        next_dp = [
            [None] * (budget + 1)
            for _ in range(min(gap_limit, i + 1) + 1)
        ]
        keep_row = next_dp[0]

        for gap, row in enumerate(dp):
            # Before processing index i, gap == 0 means index i-1
            # was kept, except at the start of the conversation.
            gain = value + (bonus if i > 0 and gap == 0 else 0)

            drop_row = (
                next_dp[gap + 1]
                if not pinned and gap < gap_limit
                else None
            )

            for used, score in enumerate(row):
                if score is None:
                    continue

                # Keep this message.
                new_used = used + length
                if new_used <= budget:
                    candidate = score + gain
                    old = keep_row[new_used]
                    if old is None or candidate > old:
                        keep_row[new_used] = candidate

                # Drop this message, unless pinned or the gap is too long.
                if drop_row is not None:
                    old = drop_row[used]
                    if old is None or score > old:
                        drop_row[used] = score

        dp = next_dp

    return max(
        (score for row in dp for score in row if score is not None),
        default=None,
    )

def min_pruning_cost(parent, demand, cap, cut_cost, critical,
                     root_cap, penalty):
    """Return the minimum feasible pruning cost, or None."""
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Parent-before-child order, independent of node labels.
    # Reversing it gives a valid bottom-up processing order.
    order = [0]
    for v in order:
        order.extend(children[v])

    subtree_demand = [0] * n
    has_critical = [False] * n

    # dp[v] is a sorted list of (retained_load, minimum_cost) pairs,
    # conditional on v being retained. The cost excludes line v.
    dp = [[] for _ in range(n)]
    INF = float("inf")

    for v in reversed(order):
        subtree_demand[v] = demand[v] + sum(
            subtree_demand[u] for u in children[v]
        )
        has_critical[v] = critical[v] or any(
            has_critical[u] for u in children[v]
        )

        limit = root_cap if v == 0 else cap[v]
        limit = min(limit, subtree_demand[v])

        if demand[v] > limit:
            # Retaining v itself is impossible.
            continue

        states = [(demand[v], 0)]

        for u in children[v]:
            # Keeping line u uses one of the feasible retained states.
            options = dp[u]

            # Cutting line u is permitted only if its entire subtree
            # contains no critical node.
            if not has_critical[u]:
                drop_cost = (
                    cut_cost[u] + penalty * subtree_demand[u]
                )

                # Both keeping and cutting may contribute zero load.
                # Keep only the cheaper zero-load option.
                if options and options[0][0] == 0:
                    if drop_cost < options[0][1]:
                        options = [(0, drop_cost)] + options[1:]
                else:
                    options = [(0, drop_cost)] + options

            if not options:
                states = []
                break

            max_load = min(
                limit, states[-1][0] + options[-1][0]
            )
            merged = [INF] * (max_load + 1)

            for current_load, current_cost in states:
                room = limit - current_load

                for child_load, child_cost in options:
                    # options is sorted by load.
                    if child_load > room:
                        break

                    load = current_load + child_load
                    cost = current_cost + child_cost
                    if cost < merged[load]:
                        merged[load] = cost

            states = [
                (load, cost)
                for load, cost in enumerate(merged)
                if cost != INF
            ]

            if not states:
                break

        dp[v] = states

    if not dp[0]:
        return None
    return min(cost for _, cost in dp[0])

def simulate_vending(prices, stock, bank, events, timeout):
    # Validate ordering before running any part of the simulation.
    previous_t = -1
    for t, kind, arg in events:
        if t < previous_t:
            raise ValueError("Event times must be non-decreasing")
        previous_t = t

    ascending = (5, 10, 25, 100)
    descending = (100, 25, 10, 5)

    bank_counts = {d: bank.get(d, 0) for d in ascending}
    stock_left = stock.copy()
    escrow = []
    escrow_total = 0
    last = None
    log = []

    for t, kind, arg in events:
        # A timeout takes precedence over an event at the same time.
        if escrow and t >= last + timeout:
            log.append(
                ("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True)))
            )
            escrow.clear()
            escrow_total = 0

        if kind == "coin":
            if arg not in bank_counts or len(escrow) == 10:
                log.append(("REJECT", t, arg))
                continue  # Rejected coins do not update activity time.

            escrow.append(arg)
            escrow_total += arg

        elif kind == "select":
            if arg not in prices:
                log.append(("UNKNOWN", t, arg))

            elif stock_left[arg] == 0:
                log.append(("SOLD_OUT", t, arg))

            elif escrow_total < prices[arg]:
                log.append(("NEED", t, prices[arg] - escrow_total))

            else:
                # Work on a tentative bank so failure needs no rollback.
                tentative = bank_counts.copy()
                for coin in escrow:
                    tentative[coin] += 1

                remaining = escrow_total - prices[arg]
                change_coins = []

                for d in descending:
                    count = min(tentative[d], remaining // d)
                    tentative[d] -= count
                    remaining -= count * d
                    change_coins.extend([d] * count)

                if remaining:
                    log.append(("EXACT_ONLY", t, arg))
                else:
                    bank_counts = tentative
                    stock_left[arg] -= 1
                    escrow.clear()
                    escrow_total = 0
                    log.append(("VEND", t, arg, tuple(change_coins)))

        elif kind == "cancel":
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow.clear()
                escrow_total = 0

        else:
            raise ValueError(f"Unknown event kind: {kind!r}")

        # Every select/cancel and every accepted coin is an activity.
        last = t

    if escrow:
        log.append(
            ("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True)))
        )

    final_bank = tuple(bank_counts[d] for d in ascending)
    return log, final_bank

import re


def evaluate_access(rules, requests) -> list[str]:
    name_re = re.compile(r"[a-z0-9_]+")
    word_re = re.compile(r"[a-z]+")
    principal_re = re.compile(r"(?:\*|(?:user|group):[a-z0-9_]+)")
    action_re = re.compile(r"(?:\*|[a-z]+(?:,[a-z]+)*)")

    resource_segment = r"(?:\*\*|\*|[a-z0-9._-]+)"
    resource_re = re.compile(
        rf"/(?:{resource_segment}(?:/{resource_segment})*)?"
    )
    path_re = re.compile(r"/(?:[a-z0-9._-]+(?:/[a-z0-9._-]+)*)?")

    def valid_string(pattern, value):
        return isinstance(value, str) and pattern.fullmatch(value) is not None

    def segments(path):
        return [] if path == "/" else path[1:].split("/")

    # Validate all input before performing any access evaluation.
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    parsed_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")

        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(
                f"rule {i}: expected 4 fields, got {len(fields)}"
            )

        effect, principal, action, resource = fields
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        if principal_re.fullmatch(principal) is None:
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        if action_re.fullmatch(action) is None:
            raise ValueError(f"rule {i}: bad action {action!r}")
        if resource_re.fullmatch(resource) is None:
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        parsed_rules.append((effect, principal, action, resource))

    for j, request in enumerate(requests):
        if not isinstance(request, tuple) or len(request) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")

        user, groups, action, path = request
        if not valid_string(name_re, user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if (
            not isinstance(groups, list)
            or any(not valid_string(name_re, group) for group in groups)
        ):
            raise ValueError(f"request {j}: bad groups")
        if not valid_string(word_re, action):
            raise ValueError(f"request {j}: bad action {action!r}")
        if not valid_string(path_re, path):
            raise ValueError(f"request {j}: bad path {path!r}")

    compiled = []
    for i, (effect, principal, action, resource) in enumerate(parsed_rules):
        tokens = segments(resource)
        literal_count = sum(token not in ("*", "**") for token in tokens)
        principal_score = (
            0 if principal == "*" else 2 if principal.startswith("user:") else 1
        )
        actions = None if action == "*" else frozenset(action.split(","))

        # First matching rule in this order is the winning rule:
        # specificity, then DENY, then smallest original index.
        rank = (
            literal_count,
            principal_score,
            int(actions is not None),
            int(effect == "DENY"),
            -i,
        )

        # Consecutive "**" tokens are equivalent to a single "**".
        # Collapsing them makes epsilon closure a single bit operation.
        collapsed = []
        for token in tokens:
            if token == "**" and collapsed and collapsed[-1] == "**":
                continue
            collapsed.append(token)

        # Bit k represents the state immediately before token k.
        literal_masks = {}
        one_mask = 0
        many_mask = 0
        for k, token in enumerate(collapsed):
            bit = 1 << k
            if token == "*":
                one_mask |= bit
            elif token == "**":
                many_mask |= bit
            else:
                literal_masks[token] = literal_masks.get(token, 0) | bit

        initial = 1
        initial |= (initial & many_mask) << 1
        accept = 1 << len(collapsed)

        compiled.append((
            rank, i, effect, principal, actions,
            literal_masks, one_mask, many_mask, initial, accept,
        ))

    compiled.sort(key=lambda rule: rule[0], reverse=True)

    decisions = []
    for user, groups, action, path in requests:
        group_set = set(groups)
        path_segments = segments(path)
        decision = "DENY by default"

        for (
            _, i, effect, principal, actions,
            literal_masks, one_mask, many_mask, initial, accept,
        ) in compiled:
            if principal != "*":
                if principal.startswith("user:"):
                    if principal[5:] != user:
                        continue
                elif principal[6:] not in group_set:
                    continue

            if actions is not None and action not in actions:
                continue

            states = initial
            for segment in path_segments:
                # Literals and "*" advance; "**" can consume and stay.
                advancing = one_mask | literal_masks.get(segment, 0)
                states = (
                    ((states & advancing) << 1)
                    | (states & many_mask)
                )

                # "**" may also consume zero segments.
                states |= (states & many_mask) << 1
                if not states:
                    break

            if states & accept:
                decision = f"{effect} by rule {i}"
                break

        decisions.append(decision)

    return decisions

import json
import re
from copy import deepcopy


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    merged = {}
    warnings = []
    identifier = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

    def type_name(value):
        # Check bool separately because bool is a subclass of int.
        if value is None:
            return "null"
        if isinstance(value, bool):
            return "bool"
        if isinstance(value, dict):
            return "dict"
        if isinstance(value, list):
            return "list"
        if isinstance(value, str):
            return "str"
        if isinstance(value, int):
            return "int"
        if isinstance(value, float):
            return "float"
        raise TypeError("unsupported non-JSON value")

    def child_path(path, name):
        if identifier.fullmatch(name):
            return path + "." + name
        return path + "[" + json.dumps(name, ensure_ascii=False) + "]"

    def merge_into(target, overlay, path, layer_index):
        for key, value in overlay.items():
            if not isinstance(key, str):
                raise TypeError(
                    f"layer {layer_index}: non-string key at {path}"
                )

            if key.startswith("-"):
                directive, name = "delete", key[1:]
            elif key.endswith("+"):
                directive, name = "append", key[:-1]
            else:
                directive, name = "set", key

            if not name:
                raise ValueError(
                    f"layer {layer_index}: empty key name at {path}"
                )

            location = child_path(path, name)

            if directive == "delete":
                if value is not None:
                    raise ValueError(
                        f"layer {layer_index}: delete directive needs null "
                        f"at {location}"
                    )
                if name in target:
                    del target[name]
                else:
                    warnings.append(
                        f"layer {layer_index}: delete of missing key "
                        f"at {location}"
                    )

            elif directive == "append":
                if not isinstance(value, list):
                    raise ValueError(
                        f"layer {layer_index}: append directive needs a list "
                        f"at {location}"
                    )
                if name not in target:
                    target[name] = deepcopy(value)
                elif isinstance(target[name], list):
                    target[name].extend(deepcopy(value))
                else:
                    raise ValueError(
                        f"layer {layer_index}: cannot append to "
                        f"{type_name(target[name])} at {location}"
                    )

            else:
                if name in target:
                    old_type = type_name(target[name])
                    new_type = type_name(value)
                    if old_type != new_type:
                        warnings.append(
                            f"layer {layer_index}: type change at {location}: "
                            f"{old_type} -> {new_type}"
                        )

                if isinstance(value, dict):
                    if name not in target or not isinstance(target[name], dict):
                        target[name] = {}
                    merge_into(target[name], value, location, layer_index)
                else:
                    # Lists are copied without interpreting nested directives.
                    target[name] = deepcopy(value)

    for layer_index, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {layer_index} is not a dict")
        merge_into(merged, layer, "$", layer_index)

    return merged, warnings

import operator
import re

_PART = r"(?:0|[1-9][0-9]*)"
_VERSION = re.compile(
    rf"({_PART})\.({_PART})\.({_PART})(?:~rc([1-9][0-9]*))?"
)
_WILDCARD = re.compile(rf"({_PART})(?:\.({_PART}))?\.\*")
_AT = re.compile(rf"@({_PART})\.({_PART})")
_COMPARISON = re.compile(r"(>=|<=|!=|=|>|<)?(.+)")

_COMPARATORS = {
    "=": operator.eq,
    "!=": operator.ne,
    ">": operator.gt,
    ">=": operator.ge,
    "<": operator.lt,
    "<=": operator.le,
}


def _number_key(text):
    # Canonical decimal strings compare numerically by length, then text.
    # This also handles integers beyond Python's int-conversion digit limit.
    return len(text), text


def _version_key(text):
    match = _VERSION.fullmatch(text)
    if match is None:
        return None

    major, minor, patch, rc = match.groups()
    return (
        _number_key(major),
        _number_key(minor),
        _number_key(patch),
        rc is None,  # A plain release sorts after all its release candidates.
        _number_key(rc) if rc is not None else (0, ""),
    )


def _parse_clause(clause):
    if clause == "*":
        return "*", None

    match = _WILDCARD.fullmatch(clause)
    if match is not None:
        major, minor = match.groups()
        if minor is None:
            return "major", _number_key(major)
        return "minor", (_number_key(major), _number_key(minor))

    match = _AT.fullmatch(clause)
    if match is not None:
        major, minor = match.groups()
        return "@", (_number_key(major), _number_key(minor))

    match = _COMPARISON.fullmatch(clause)
    if match is not None:
        op, version = match.groups()
        key = _version_key(version)
        if key is not None:
            return op or "=", key

    return None


def _matches_clause(key, clause):
    op, target = clause

    if op == "*":
        return True
    if op == "major":
        return key[0] == target
    if op == "minor":
        return key[:2] == target
    if op == "@":
        return key[0] == target[0] and key[1] >= target[1]

    return _COMPARATORS[op](key, target)


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    versions = []
    for i, element in enumerate(available):
        key = _version_key(element) if isinstance(element, str) else None
        if key is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        versions.append((key, element))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    # Fully validate and compile the constraint before matching anything.
    alternatives = []
    for a, text in enumerate(constraint.split("|"), start=1):
        text = text.strip(" ")
        allows_rc = text.startswith("?")
        if allows_rc:
            text = text[1:].strip(" ")

        if text == "":
            raise ValueError(f"alternative {a} is empty")

        clauses = []
        for c, clause in enumerate(text.split(","), start=1):
            clause = clause.strip(" ")
            parsed = _parse_clause(clause)
            if parsed is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            clauses.append(parsed)

        alternatives.append((allows_rc, clauses))

    best_key = None
    best_version = None

    for key, version in versions:
        matches = any(
            (key[3] or allows_rc)
            and all(_matches_clause(key, clause) for clause in clauses)
            for allows_rc, clauses in alternatives
        )
        if matches and (best_key is None or key > best_key):
            best_key = key
            best_version = version

    return best_version

def parse_outline(text: str) -> tuple:
    import re

    key_pattern = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*")
    int_pattern = re.compile(r"-?(?:0|[1-9][0-9]*)")
    escapes = {"\\": "\\", '"': '"', "n": "\n", "t": "\t"}

    def parse_scalar(s):
        # Returns (error_message_or_None, value).
        if s.startswith('"'):
            chars = []
            i = 1
            while i < len(s):
                c = s[i]
                if c == "\\":
                    i += 1
                    if i == len(s) or s[i] not in escapes:
                        return "bad escape", None
                    chars.append(escapes[s[i]])
                elif c == '"':
                    if i != len(s) - 1:
                        return "bad string", None
                    return None, "".join(chars)
                else:
                    chars.append(c)
                i += 1
            return "bad string", None

        if s == "true":
            return None, True
        if s == "false":
            return None, False
        if s == "null":
            return None, None

        if int_pattern.fullmatch(s):
            try:
                return None, int(s)
            except ValueError:
                # Avoid Python's configurable limit on decimal int conversion.
                # Each chunk is below the minimum nonzero limit.
                negative = s.startswith("-")
                digits = s[1:] if negative else s
                value = 0
                chunk_size = 500
                first_size = len(digits) % chunk_size or chunk_size
                value = int(digits[:first_size])
                for i in range(first_size, len(digits), chunk_size):
                    value = value * (10 ** chunk_size) + int(
                        digits[i:i + chunk_size]
                    )
                return None, -value if negative else value

        return None, s

    # Frames are (indent, kind, container), where kind is "key" or "item".
    stack = []
    root = None

    # A pending opener is (parent_container, key_or_list_index, indent).
    # Its value is initially None, and is replaced if a child block follows.
    pending = None

    for line_number, line in enumerate(text.split("\n"), 1):
        rest = line.lstrip(" \t")
        if not rest or rest.startswith("#"):
            continue

        indent = len(line) - len(rest)
        if "\t" in line[:indent]:
            return "error", line_number, "tab in indentation"

        # Fully validate this line's syntax before checking structure.
        if rest == "-" or rest.startswith("- "):
            kind = "item"
            key = None
            scalar_text = rest[2:].strip(" ")
            opener = not scalar_text
        else:
            kind = "key"
            colon = rest.find(":")
            if colon < 0:
                return "error", line_number, "invalid entry"

            key = rest[:colon]
            if not key_pattern.fullmatch(key):
                return "error", line_number, "invalid entry"

            after = rest[colon + 1:]
            scalar_text = after.strip(" ")
            opener = not scalar_text
            if not opener and not after.startswith(" "):
                return "error", line_number, "invalid entry"

        value = None
        if not opener:
            error, value = parse_scalar(scalar_text)
            if error is not None:
                return "error", line_number, error

        if not stack:
            if indent != 0:
                return "error", line_number, "unexpected indent"
            root = {} if kind == "key" else []
            stack.append((indent, kind, root))

        elif pending is not None and indent > pending[2]:
            child = {} if kind == "key" else []
            parent, slot, _ = pending
            parent[slot] = child
            stack.append((indent, kind, child))

        else:
            if indent > stack[-1][0]:
                return "error", line_number, "unexpected indent"

            while stack and indent < stack[-1][0]:
                stack.pop()

            if not stack or indent != stack[-1][0]:
                return "error", line_number, "inconsistent dedent"

        pending = None
        _, block_kind, container = stack[-1]

        if kind != block_kind:
            return "error", line_number, "mixed block"

        if kind == "key":
            if key in container:
                return "error", line_number, f"duplicate key '{key}'"
            container[key] = value
            slot = key
        else:
            slot = len(container)
            container.append(value)

        if opener:
            pending = (container, slot, indent)

    return "ok", root

import re


def run_pile(src: str, max_steps: int) -> tuple:
    # Only these four characters are whitespace.
    tokens = re.findall(r"[^\x20\t\n\r\[\]]+|[\[\]]", src)
    is_int = re.compile(r"-?[0-9]+").fullmatch
    n = len(tokens)

    builtin_names = (
        "dup", "drop", "swap", "over", "rot",
        "+", "-", "*", "/", "%", "<", "=",
        "if", "times", "while", "call", "dip",
    )
    builtin_codes = {
        name: code for code, name in enumerate(builtin_names, 4)
    }

    # Opcodes: 0 = user word, 1 = integer, 2 = quotation,
    #          3 = definition, 4..20 = builtins.
    code = bytearray(n)
    close = [0] * n
    opens = []

    # Complete structural validation before any execution.
    i = 0
    while i < n:
        token = tokens[i]

        if token == "[":
            code[i] = 2
            opens.append(i)

        elif token == "]":
            if not opens or tokens[opens[-1]] != "[":
                return ("error", i, "unmatched ]")
            close[opens.pop()] = i

        elif token == ":":
            if opens:
                return ("error", i, "misplaced :")
            if i + 1 == n:
                return ("error", i, "unclosed :")

            name = tokens[i + 1]
            if (
                name in ("[", "]", ":", ";")
                or name in builtin_codes
                or is_int(name) is not None
            ):
                return ("error", i + 1, "bad name")

            code[i] = 3
            opens.append(i)
            i += 1  # Consume NAME without scanning it as a construct.

        elif token == ";":
            if not opens or tokens[opens[-1]] != ":":
                return ("error", i, "unmatched ;")
            close[opens.pop()] = i

        else:
            op = builtin_codes.get(token)
            if op is not None:
                code[i] = op
            elif is_int(token) is not None:
                code[i] = 1

        i += 1

    if opens:
        first = opens[0]
        message = "unclosed [" if tokens[first] == "[" else "unclosed :"
        return ("error", first, message)

    class Quote:
        __slots__ = ("start", "end")

        def __init__(self, start, end):
            self.start = start
            self.end = end

    def parse_integer(text):
        # Chunking avoids Python's configurable decimal-string digit limit.
        if len(text) <= 18:
            return int(text)

        negative = text[0] == "-"
        digits = text[1:] if negative else text
        first_size = len(digits) % 18 or 18
        value = int(digits[:first_size])
        for pos in range(first_size, len(digits), 18):
            value = value * 10**18 + int(digits[pos:pos + 18])
        return -value if negative else value

    integer_cache = {}
    quote_cache = {}
    definitions = {}
    stack = []
    steps = 0

    arity = (
        0, 0, 0, 0,
        1, 1, 2, 2, 3,       # dup drop swap over rot
        2, 2, 2, 2, 2, 2, 2, # arithmetic and comparisons
        3, 2, 2, 1, 2,       # if times while call dip
    )

    # Explicit execution frames:
    #   [0, next_token, end]           sequence
    #   [1, quote, remaining]          times
    #   [2, condition, body, index, phase]  while
    #   [3, saved_value]               dip restoration
    frames = [[0, 0, n]]

    while frames:
        frame = frames[-1]
        kind = frame[0]

        if kind == 1:
            if frame[2] == 0:
                frames.pop()
            else:
                frame[2] -= 1
                q = frame[1]
                frames.append([0, q.start, q.end])
            continue

        if kind == 2:
            condition, body, while_index = frame[1:4]

            if frame[4] == 0:
                frame[4] = 1
                if condition.start != condition.end:
                    frames.append([0, condition.start, condition.end])
            else:
                if not stack:
                    return ("error", while_index, "stack underflow")
                value = stack.pop()
                if type(value) is not int:
                    return ("error", while_index, "type error")

                if value == 0:
                    frames.pop()
                else:
                    frame[4] = 0
                    if body.start != body.end:
                        frames.append([0, body.start, body.end])
            continue

        if kind == 3:
            stack.append(frame[1])
            frames.pop()
            continue

        i, end = frame[1], frame[2]
        if i == end:
            frames.pop()
            continue

        if steps >= max_steps:
            return ("error", i, "step limit exceeded")
        steps += 1

        op = code[i]
        frame[1] = i + 1

        if op == 1:
            value = integer_cache.get(i)
            if value is None:
                value = parse_integer(tokens[i])
                integer_cache[i] = value
            stack.append(value)
            continue

        if op == 2:
            frame[1] = close[i] + 1
            q = quote_cache.get(i)
            if q is None:
                q = Quote(i + 1, close[i])
                quote_cache[i] = q
            stack.append(q)
            continue

        if op == 3:
            frame[1] = close[i] + 1
            definitions[tokens[i + 1]] = (i + 2, close[i])
            continue

        if op == 0:
            body = definitions.get(tokens[i])
            if body is None:
                return ("error", i, f"unknown word '{tokens[i]}'")
            if body[0] != body[1]:
                frames.append([0, body[0], body[1]])
            continue

        # Check arity first, then types, then exceptional operand values.
        if len(stack) < arity[op]:
            return ("error", i, "stack underflow")

        if 9 <= op <= 15:
            a, b = stack[-2], stack[-1]
            if type(a) is not int or type(b) is not int:
                return ("error", i, "type error")
            if op in (12, 13) and b == 0:
                return ("error", i, "division by zero")

        elif op == 16:  # if
            c, t, f = stack[-3], stack[-2], stack[-1]
            if (
                type(c) is not int
                or type(t) is not Quote
                or type(f) is not Quote
            ):
                return ("error", i, "type error")

        elif op == 17:  # times
            q, count = stack[-2], stack[-1]
            if type(q) is not Quote or type(count) is not int:
                return ("error", i, "type error")
            if count < 0:
                return ("error", i, "negative count")

        elif op == 18:  # while
            condition, body = stack[-2], stack[-1]
            if type(condition) is not Quote or type(body) is not Quote:
                return ("error", i, "type error")

        elif op in (19, 20):  # call, dip
            if type(stack[-1]) is not Quote:
                return ("error", i, "type error")

        if op == 4:  # dup
            stack.append(stack[-1])

        elif op == 5:  # drop
            stack.pop()

        elif op == 6:  # swap
            stack[-2], stack[-1] = stack[-1], stack[-2]

        elif op == 7:  # over
            stack.append(stack[-2])

        elif op == 8:  # rot
            stack[-3], stack[-2], stack[-1] = (
                stack[-2], stack[-1], stack[-3]
            )

        elif 9 <= op <= 15:
            stack.pop()
            if op == 9:
                result = a + b
            elif op == 10:
                result = a - b
            elif op == 11:
                result = a * b
            elif op == 12:
                result = a // b
            elif op == 13:
                result = a % b
            elif op == 14:
                result = int(a < b)
            else:
                result = int(a == b)
            stack[-1] = result

        elif op == 16:  # if
            del stack[-3:]
            q = t if c != 0 else f
            if q.start != q.end:
                frames.append([0, q.start, q.end])

        elif op == 17:  # times
            del stack[-2:]
            # An empty quotation takes no steps, regardless of count.
            if count and q.start != q.end:
                frames.append([1, q, count])

        elif op == 18:  # while
            del stack[-2:]
            frames.append([2, condition, body, i, 0])

        elif op == 19:  # call
            q = stack.pop()
            if q.start != q.end:
                frames.append([0, q.start, q.end])

        else:  # dip
            q = stack.pop()
            saved = stack.pop()
            if q.start == q.end:
                stack.append(saved)
            else:
                frames.append([3, saved])
                frames.append([0, q.start, q.end])

    # Render quotations iteratively. Memoization also avoids repeatedly
    # rendering the same quotation when it occurs multiple times on the stack.
    rendered = {}

    def render_quote(q):
        opening = q.start - 1
        existing = rendered.get(opening)
        if existing is not None:
            return existing

        result = []
        rendered[opening] = result
        work = [[q.start, q.end, result]]

        while work:
            item = work[-1]
            pos, end, output = item

            if pos == end:
                work.pop()
                continue

            if tokens[pos] == "[":
                item[0] = close[pos] + 1
                child = rendered.get(pos)
                if child is None:
                    child = []
                    rendered[pos] = child
                    output.append(child)
                    work.append([pos + 1, close[pos], child])
                else:
                    output.append(child)
            else:
                output.append(tokens[pos])
                item[0] = pos + 1

        return result

    return (
        "ok",
        [
            value if type(value) is int else render_quote(value)
            for value in stack
        ],
    )

def filter_records(query: str, records: list[dict]) -> tuple:
    # Token: (kind, start_position, end_position, decoded_value)
    tokens = []
    n = len(query)
    i = 0

    def is_digit(c):
        return "0" <= c <= "9"

    def is_letter(c):
        return "a" <= c <= "z" or "A" <= c <= "Z"

    def parse_integer(text):
        # Chunked conversion avoids Python's decimal-string conversion limit.
        negative = text[0] == "-"
        start = 1 if negative else 0
        value = 0
        while start < len(text):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
            start += len(chunk)
        return -value if negative else value

    keywords = {"and", "or", "not", "in", "has"}

    # STEP 1: Lex the entire query before attempting to parse it.
    while i < n:
        c = query[i]

        if c in " \t\n":
            i += 1
            continue

        start = i

        if c in "()[],":
            i += 1
            tokens.append((c, start, i, None))
            continue

        two = query[i:i + 2]
        if two in ("!=", "<=", ">="):
            i += 2
            tokens.append((two, start, i, None))
            continue

        if c in "=<>":
            i += 1
            tokens.append((c, start, i, None))
            continue

        if c == '"':
            i += 1
            chars = []

            while i < n:
                c = query[i]

                if c == '"':
                    i += 1
                    tokens.append(("STRING", start, i, "".join(chars)))
                    break

                if c == "\\":
                    if i + 1 >= n or query[i + 1] not in ('"', "\\"):
                        return ("error", i, "bad escape")
                    chars.append(query[i + 1])
                    i += 2
                else:
                    chars.append(c)
                    i += 1
            else:
                return ("error", start, "unterminated string")

            continue

        if is_digit(c) or (
            c == "-" and i + 1 < n and is_digit(query[i + 1])
        ):
            if c == "-":
                i += 1
            while i < n and is_digit(query[i]):
                i += 1
            value = parse_integer(query[start:i])
            tokens.append(("INT", start, i, value))
            continue

        if is_letter(c) or c == "_":
            i += 1
            while i < n:
                c = query[i]
                if is_letter(c) or is_digit(c) or c in "_.":
                    i += 1
                else:
                    break
            word = query[start:i]
            kind = word if word in keywords else "FIELD"
            tokens.append((kind, start, i, word))
            continue

        return ("error", i, f"unexpected character '{c}'")

    tokens.append(("END", n, n, None))

    # STEP 2: Compile to postfix instructions using an iterative parser.
    class ParseFailure(Exception):
        pass

    index = 0
    code = []
    operators = []
    precedence = {"or": 1, "and": 2, "not": 3}
    comparisons = {"=", "!=", "<", "<=", ">", ">="}

    def fail():
        kind, start, end, _ = tokens[index]
        if kind == "END":
            message = "unexpected end of input"
        else:
            message = f"unexpected token '{query[start:end]}'"
        raise ParseFailure(start, message)

    def take(kind):
        nonlocal index
        if tokens[index][0] != kind:
            fail()
        value = tokens[index][3]
        index += 1
        return value

    def take_literal():
        nonlocal index
        if tokens[index][0] not in ("INT", "STRING"):
            fail()
        value = tokens[index][3]
        index += 1
        return value

    expecting_operand = True

    try:
        while True:
            kind = tokens[index][0]

            if expecting_operand:
                if kind == "not":
                    operators.append("not")
                    index += 1
                    continue

                if kind == "(":
                    operators.append("(")
                    index += 1
                    continue

                if kind == "has":
                    index += 1
                    field = take("FIELD")
                    code.append(("has", field))

                elif kind == "FIELD":
                    field = take("FIELD")
                    kind = tokens[index][0]

                    if kind in comparisons:
                        index += 1
                        literal = take_literal()
                        code.append(("cmp", field, kind, literal))

                    elif kind == "in":
                        index += 1
                        take("[")
                        literals = [take_literal()]

                        while tokens[index][0] == ",":
                            index += 1
                            literals.append(take_literal())

                        take("]")

                        # Partition by type, preserving typed membership.
                        integers = set()
                        strings = set()
                        for literal in literals:
                            if type(literal) is int:
                                integers.add(literal)
                            else:
                                strings.add(literal)

                        code.append(("in", field, integers, strings))

                    else:
                        fail()
                else:
                    fail()

                expecting_operand = False
                continue

            # An operand has just finished.
            if kind in ("and", "or"):
                while (
                    operators
                    and operators[-1] != "("
                    and precedence[operators[-1]] >= precedence[kind]
                ):
                    code.append((operators.pop(),))

                operators.append(kind)
                index += 1
                expecting_operand = True
                continue

            if kind == ")":
                while operators and operators[-1] != "(":
                    code.append((operators.pop(),))

                if not operators:
                    fail()

                operators.pop()  # Matching '('.
                index += 1
                continue

            if kind == "END":
                while operators:
                    if operators[-1] == "(":
                        fail()
                    code.append((operators.pop(),))
                break

            fail()

    except ParseFailure as exc:
        pos, message = exc.args
        return ("error", pos, message)

    # STEP 3: Evaluate postfix instructions.
    # Ordering FALSE < UNKNOWN < TRUE makes AND=min and OR=max.
    FALSE, UNKNOWN, TRUE = 0, 1, 2
    missing = object()
    selected = []

    for record_index, record in enumerate(records):
        stack = []

        for instruction in code:
            operation = instruction[0]

            if operation == "has":
                stack.append(TRUE if instruction[1] in record else FALSE)

            elif operation == "cmp":
                _, field, comparison, literal = instruction
                value = record.get(field, missing)

                if value is missing:
                    result = UNKNOWN

                elif type(value) is not type(literal):
                    if comparison == "=":
                        result = FALSE
                    elif comparison == "!=":
                        result = TRUE
                    else:
                        result = UNKNOWN

                else:
                    if comparison == "=":
                        matched = value == literal
                    elif comparison == "!=":
                        matched = value != literal
                    elif comparison == "<":
                        matched = value < literal
                    elif comparison == "<=":
                        matched = value <= literal
                    elif comparison == ">":
                        matched = value > literal
                    else:
                        matched = value >= literal

                    result = TRUE if matched else FALSE

                stack.append(result)

            elif operation == "in":
                _, field, integers, strings = instruction
                value = record.get(field, missing)

                if value is missing:
                    result = UNKNOWN
                else:
                    candidates = integers if type(value) is int else strings
                    result = TRUE if value in candidates else FALSE

                stack.append(result)

            elif operation == "not":
                stack[-1] = 2 - stack[-1]

            elif operation == "and":
                right = stack.pop()
                left = stack[-1]
                stack[-1] = left if left < right else right

            else:  # "or"
                right = stack.pop()
                left = stack[-1]
                stack[-1] = left if left > right else right

        if stack[0] == TRUE:
            selected.append(record_index)

    return ("ok", selected)

def evaluate(src: str, env: dict) -> tuple:
    # Token: (kind, exact_text, start_position)
    tokens = []
    n = len(src)
    i = 0

    two_char_ops = {"<=", ">=", "==", "!="}
    one_char_ops = set("+-*/%^()?:<>")

    while i < n:
        c = src[i]

        if c == " ":
            i += 1
            continue

        start = i

        if "0" <= c <= "9":
            i += 1
            while i < n and "0" <= src[i] <= "9":
                i += 1
            tokens.append(("INT", src[start:i], start))

        elif "a" <= c <= "z" or c == "_":
            i += 1
            while i < n:
                c = src[i]
                if not ("a" <= c <= "z" or "0" <= c <= "9" or c == "_"):
                    break
                i += 1
            tokens.append(("NAME", src[start:i], start))

        elif src[i:i + 2] in two_char_ops:
            text = src[i:i + 2]
            tokens.append((text, text, i))
            i += 2

        elif c in one_char_ops:
            tokens.append((c, c, i))
            i += 1

        else:
            tokens.append(("INVALID", c, i))
            i += 1

    tokens.append(("END", "", n))

    def syntax_error(token):
        kind, text, pos = token
        if kind == "END":
            message = "unexpected end of input"
        elif kind == "INVALID":
            message = f"unexpected character '{text}'"
        else:
            message = f"unexpected token '{text}'"
        return ("error", pos, message)

    # Flat AST: children are indices, not recursively nested Python objects.
    #
    # ("int", text, pos)
    # ("name", text, pos)
    # ("neg", child)
    # ("bin", operator, pos, left, right)
    # ("if", condition, true_branch, false_branch)
    nodes = []
    results = []

    def add_node(node):
        results.append(len(nodes))
        nodes.append(node)

    # Explicit recursive-descent continuations.
    # Each task is (action, argument).
    tasks = [("expect", "END"), ("cond", None)]
    p = 0
    cmp_ops = {"<", "<=", ">", ">=", "==", "!="}

    while tasks:
        action, arg = tasks.pop()
        token = tokens[p]
        kind, text, pos = token

        if action == "expect":
            if kind != arg:
                return syntax_error(token)
            p += 1

        elif action == "cond":
            tasks.append(("cond_tail", None))
            tasks.append(("cmp", None))

        elif action == "cond_tail":
            if kind == "?":
                p += 1
                # Execute: cond, ':', cond, then build the ternary.
                tasks.append(("make_if", None))
                tasks.append(("cond", None))
                tasks.append(("expect", ":"))
                tasks.append(("cond", None))

        elif action == "cmp":
            tasks.append(("cmp_tail", None))
            tasks.append(("sum", None))

        elif action == "cmp_tail":
            if kind in cmp_ops:
                p += 1
                # No subsequent cmp_tail: comparisons are non-associative.
                tasks.append(("make_bin", (kind, pos)))
                tasks.append(("sum", None))

        elif action == "sum":
            tasks.append(("sum_tail", None))
            tasks.append(("term", None))

        elif action == "sum_tail":
            if kind in ("+", "-"):
                p += 1
                tasks.append(("sum_tail", None))
                tasks.append(("make_bin", (kind, pos)))
                tasks.append(("term", None))

        elif action == "term":
            tasks.append(("term_tail", None))
            tasks.append(("unary", None))

        elif action == "term_tail":
            if kind in ("*", "/", "%"):
                p += 1
                tasks.append(("term_tail", None))
                tasks.append(("make_bin", (kind, pos)))
                tasks.append(("unary", None))

        elif action == "unary":
            if kind == "-":
                p += 1
                tasks.append(("make_neg", None))
                tasks.append(("unary", None))
            else:
                tasks.append(("power", None))

        elif action == "power":
            tasks.append(("power_tail", None))
            tasks.append(("atom", None))

        elif action == "power_tail":
            if kind == "^":
                p += 1
                tasks.append(("make_bin", (kind, pos)))
                tasks.append(("unary", None))

        elif action == "atom":
            if kind == "INT":
                add_node(("int", text, pos))
                p += 1
            elif kind == "NAME":
                add_node(("name", text, pos))
                p += 1
            elif kind == "(":
                p += 1
                tasks.append(("expect", ")"))
                tasks.append(("cond", None))
            else:
                return syntax_error(token)

        elif action == "make_neg":
            child = results.pop()
            add_node(("neg", child))

        elif action == "make_bin":
            right = results.pop()
            left = results.pop()
            op, op_pos = arg
            add_node(("bin", op, op_pos, left, right))

        elif action == "make_if":
            false_branch = results.pop()
            true_branch = results.pop()
            condition = results.pop()
            add_node(("if", condition, true_branch, false_branch))

    root = results.pop()

    # These are no longer needed during evaluation.
    del tokens, results, tasks

    def decimal_int(text):
        """Convert arbitrary-length ASCII decimal without changing global limits."""
        if len(text) <= 600:
            # Below Python's minimum configurable decimal-conversion limit.
            return int(text)

        # Balanced combination avoids both the decimal-conversion limit and
        # repeatedly multiplying an ever-growing integer by a small base.
        parts = [
            (int(text[j:j + 9]), len(text[j:j + 9]))
            for j in range(0, len(text), 9)
        ]
        powers = {}

        while len(parts) > 1:
            combined = []
            end = len(parts) - 1

            for j in range(0, end, 2):
                left, left_width = parts[j]
                right, right_width = parts[j + 1]

                scale = powers.get(right_width)
                if scale is None:
                    scale = 10 ** right_width
                    powers[right_width] = scale

                combined.append((
                    left * scale + right,
                    left_width + right_width,
                ))

            if len(parts) % 2:
                combined.append(parts[-1])

            parts = combined

        return parts[0][0]

    # Evaluation continuations and value stack.
    work = [("visit", root)]
    values = []

    while work:
        action, index = work.pop()
        node = nodes[index]
        kind = node[0]

        if action == "visit":
            if kind == "int":
                values.append(decimal_int(node[1]))

            elif kind == "name":
                name, pos = node[1], node[2]
                try:
                    value = env[name]
                except KeyError:
                    return ("error", pos, f"unknown name '{name}'")
                values.append(value)

            elif kind == "neg":
                work.append(("apply", index))
                work.append(("visit", node[1]))

            elif kind == "bin":
                work.append(("apply", index))
                # LIFO order: evaluate left completely before right.
                work.append(("visit", node[4]))
                work.append(("visit", node[3]))

            else:  # kind == "if"
                work.append(("choose", index))
                work.append(("visit", node[1]))

        elif action == "choose":
            condition = values.pop()
            branch = node[2] if condition != 0 else node[3]
            work.append(("visit", branch))

        else:  # action == "apply"
            if kind == "neg":
                values.append(-values.pop())
                continue

            right = values.pop()
            left = values.pop()
            op, pos = node[1], node[2]

            if op == "+":
                value = left + right
            elif op == "-":
                value = left - right
            elif op == "*":
                value = left * right
            elif op == "/":
                if right == 0:
                    return ("error", pos, "division by zero")
                value = left // right
            elif op == "%":
                if right == 0:
                    return ("error", pos, "division by zero")
                value = left % right
            elif op == "^":
                if right < 0:
                    return ("error", pos, "negative exponent")
                if right > 256:
                    return ("error", pos, "exponent too large")
                value = left ** right
            elif op == "<":
                value = int(left < right)
            elif op == "<=":
                value = int(left <= right)
            elif op == ">":
                value = int(left > right)
            elif op == ">=":
                value = int(left >= right)
            elif op == "==":
                value = int(left == right)
            else:  # op == "!="
                value = int(left != right)

            values.append(value)

    return ("ok", values.pop())

def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0:
        raise ValueError("q must be nonzero")
    if not 2 <= base <= 36:
        raise ValueError("base must be in 2..36")
    if k < 0:
        raise ValueError("k must be nonnegative")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    negative = (p < 0) != (q < 0)
    p, q = abs(p), abs(q)

    def encode(n: int) -> str:
        # Decimal conversions here are always small enough to avoid
        # Python's default int-to-str digit limit.
        if base == 10:
            return str(n)
        if n == 0:
            return "0"
        chars = []
        while n:
            n, d = divmod(n, base)
            chars.append(digits[d])
        return "".join(reversed(chars))

    integer, remainder = divmod(p, q)

    # Parity of floor(|x| * base**digits_generated).
    parity = integer & 1
    fraction = []

    # Generate small blocks by long division, never constructing base**k
    # or the potentially enormous scaled integer.
    block_width = 32
    block_radix = base ** block_width
    remaining = k

    while remaining and remainder:
        width = min(block_width, remaining)
        radix = block_radix if width == block_width else base ** width

        block, remainder = divmod(remainder * radix, q)
        fraction.extend(encode(block).zfill(width))
        parity = (parity * (radix & 1) + block) & 1
        remaining -= width

    # If generation stopped early, the expansion is exact and the
    # omitted digits are all zero, so no rounding is needed.
    twice_remainder = remainder * 2
    round_up = (
        twice_remainder > q
        or (twice_remainder == q and parity == 1)
    )

    if round_up:
        # A carried-over suffix becomes zeros, which would be removed
        # from the output anyway; discard it directly.
        largest_digit = digits[base - 1]
        while fraction and fraction[-1] == largest_digit:
            fraction.pop()

        if fraction:
            fraction[-1] = digits[digits.index(fraction[-1]) + 1]
        else:
            integer += 1

    while fraction and fraction[-1] == "0":
        fraction.pop()

    if integer == 0 and not fraction:
        return "0"

    result = encode(integer)
    if fraction:
        result += "." + "".join(fraction)
    return "-" + result if negative else result

import re
from math import gcd

_DECIMAL_LITERAL = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)"
    r"(?:[eE][+-]?[0-9]+)?"
)


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if max_num < 0 or max_den < 1:
        raise ValueError("invalid numerator or denominator bound")
    if _DECIMAL_LITERAL.fullmatch(x) is None:
        raise ValueError("invalid decimal literal")

    negative = x.startswith("-")
    unsigned = x[1:] if x.startswith(("+", "-")) else x

    parts = re.split(r"[eE]", unsigned, maxsplit=1)
    mantissa = parts[0]

    exponent = 0
    if len(parts) == 2:
        exp_text = parts[1]
        exp_negative = exp_text.startswith("-")
        # Remove leading zeros before int(), including arbitrarily many
        # leading zeros in an otherwise small exponent.
        exp_digits = exp_text.lstrip("+-").lstrip("0")
        exponent = int(exp_digits or "0")
        if exp_negative:
            exponent = -exponent

    whole, _, fractional = mantissa.partition(".")
    n = int(whole + fractional)

    if n == 0 or max_num == 0:
        return "0/1"

    # The exact absolute value of x is n/d.
    scale = len(fractional) - exponent
    if scale >= 0:
        d = 10 ** scale
    else:
        n *= 10 ** (-scale)
        d = 1

    common = gcd(n, d)
    n //= common
    d //= common

    def render(a: int, b: int) -> str:
        # All fractions produced by the search are already reduced.
        if negative and a:
            a = -a
        return f"{a}/{b}"

    # No feasible positive value exceeds max_num.
    if n >= max_num * d:
        return render(max_num, 1)

    # Stern–Brocot neighbors L = la/lb and R = ra/rb.
    # Initially R = 1/0 represents positive infinity.
    la, lb = 0, 1
    ra, rb = 1, 0

    while True:
        ma, mb = la + ra, lb + rb

        if ma > max_num or mb > max_den:
            break

        # Positive distances from the target, with denominators omitted:
        # n/d - L = alpha / (d*lb)
        # R - n/d = beta / (d*rb), when rb != 0.
        alpha = n * lb - d * la
        beta = d * ra - n * rb

        if alpha == beta:
            # The mediant equals the target exactly.
            return render(ma, mb)

        if alpha > beta:
            # Move L to L + k*R, using pair arithmetic.
            k = alpha // beta
            k = min(k, (max_num - la) // ra)
            if rb:
                k = min(k, (max_den - lb) // rb)

            la += k * ra
            lb += k * rb

            if n * lb == d * la:
                return render(la, lb)
        else:
            # Move R to R + k*L.
            k = beta // alpha
            if la:
                k = min(k, (max_num - ra) // la)
            k = min(k, (max_den - rb) // lb)

            ra += k * la
            rb += k * lb

            if n * rb == d * ra:
                return render(ra, rb)

    # Only the two bracketing endpoints can be optimal.
    if rb == 0:
        return render(la, lb)

    # Compare exact errors by cross multiplication.
    left_error = (n * lb - d * la) * rb
    right_error = (d * ra - n * rb) * lb

    if left_error < right_error:
        return render(la, lb)
    if right_error < left_error:
        return render(ra, rb)

    # Equal errors: smaller reduced denominator wins.
    if lb < rb:
        return render(la, lb)
    if rb < lb:
        return render(ra, rb)

    # Equal denominators too: L has smaller absolute value.
    return render(la, lb)

from array import array


def run_ops(ops: list[tuple]) -> list:
    if not ops:
        return []

    # Include every time used as a boundary, but not first_fit's duration.
    points = {0}
    max_duration = 1

    for op in ops:
        kind = op[0]
        if kind == "cancel":
            points.add(op[1])
        elif kind == "first_fit":
            points.add(op[1])
            max_duration = max(max_duration, op[2])
        else:  # book or free_between
            points.add(op[1])
            points.add(op[2])

    # No booking extends beyond the largest input boundary. This extra
    # interval is long enough to answer every first_fit query.
    right = max(points) + max_duration
    points.add(right)

    xs = sorted(points)
    index = {x: i for i, x in enumerate(xs)}
    n = len(xs) - 1  # Leaves represent [xs[i], xs[i + 1]).

    size = 4 * n + 8
    occupied = array("q", [0]) * size
    prefix = array("q", [0]) * size
    suffix = array("q", [0]) * size
    longest = array("q", [0]) * size

    # Tags: 0 = mixed, 1 = entirely occupied, 2 = entirely free.
    tag = bytearray(size)

    def paint(v, lo, hi, busy):
        length = xs[hi] - xs[lo]
        if busy:
            occupied[v] = length
            prefix[v] = suffix[v] = longest[v] = 0
            tag[v] = 1
        else:
            occupied[v] = 0
            prefix[v] = suffix[v] = longest[v] = length
            tag[v] = 2

    def push(v, lo, mid, hi):
        state = tag[v]
        if state:
            busy = state == 1
            paint(v * 2, lo, mid, busy)
            paint(v * 2 + 1, mid, hi, busy)
            tag[v] = 0

    def pull(v, lo, mid, hi):
        left = v * 2
        right_child = left + 1
        left_length = xs[mid] - xs[lo]
        right_length = xs[hi] - xs[mid]

        occupied[v] = occupied[left] + occupied[right_child]

        p = prefix[left]
        if p == left_length:
            p += prefix[right_child]
        prefix[v] = p

        s = suffix[right_child]
        if s == right_length:
            s += suffix[left]
        suffix[v] = s

        longest[v] = max(
            longest[left],
            longest[right_child],
            suffix[left] + prefix[right_child],
        )

    def assign(v, lo, hi, qlo, qhi, busy):
        if qlo <= lo and hi <= qhi:
            paint(v, lo, hi, busy)
            return

        mid = (lo + hi) // 2
        push(v, lo, mid, hi)

        if qlo < mid:
            assign(v * 2, lo, mid, qlo, qhi, busy)
        if qhi > mid:
            assign(v * 2 + 1, mid, hi, qlo, qhi, busy)

        pull(v, lo, mid, hi)

    def occupied_between(v, lo, hi, qlo, qhi):
        # All calls have a nonempty intersection with the query.
        state = tag[v]
        if state == 2:
            return 0
        if state == 1:
            return xs[min(hi, qhi)] - xs[max(lo, qlo)]

        if qlo <= lo and hi <= qhi:
            return occupied[v]

        mid = (lo + hi) // 2
        total = 0
        if qlo < mid:
            total += occupied_between(v * 2, lo, mid, qlo, qhi)
        if qhi > mid:
            total += occupied_between(v * 2 + 1, mid, hi, qlo, qhi)
        return total

    def first_fit(qlo, duration):
        # Free suffix length of the portion already examined.
        carry = 0

        def search(v, lo, hi):
            nonlocal carry

            if hi <= qlo:
                return -1

            if qlo <= lo:
                # The earliest fit might cross into this node.
                if carry + prefix[v] >= duration:
                    return xs[lo] - carry

                # No fit inside this node: skip it in constant time.
                if longest[v] < duration:
                    length = xs[hi] - xs[lo]
                    if suffix[v] == length:
                        carry += length
                    else:
                        carry = suffix[v]
                    return -1

            # Either the query starts inside this node, or a fit exists
            # somewhere inside it. Search left before right.
            mid = (lo + hi) // 2
            push(v, lo, mid, hi)

            answer = search(v * 2, lo, mid)
            if answer != -1:
                return answer
            return search(v * 2 + 1, mid, hi)

        return search(1, 0, n)

    # Initialize lazily: descendants are initialized only when needed.
    paint(1, 0, n, False)

    bookings = {}  # start -> end
    result = []

    for op in ops:
        kind = op[0]

        if kind == "book":
            _, start, end = op
            if start >= end:
                result.append("INVALID")
                continue

            lo, hi = index[start], index[end]
            if occupied_between(1, 0, n, lo, hi):
                result.append("CONFLICT")
            else:
                assign(1, 0, n, lo, hi, True)
                bookings[start] = end
                result.append(True)

        elif kind == "cancel":
            start = op[1]
            end = bookings.pop(start, None)
            if end is None:
                result.append(0)
            else:
                assign(1, 0, n, index[start], index[end], False)
                result.append(end - start)

        elif kind == "first_fit":
            _, time, duration = op
            result.append(first_fit(index[time], duration))

        else:  # free_between
            _, start, end = op
            if start >= end:
                result.append(0)
            else:
                busy = occupied_between(
                    1, 0, n, index[start], index[end]
                )
                result.append(end - start - busy)

    return result

def run_ops(ops: list[tuple]) -> list:
    from random import Random

    randbits = Random().getrandbits

    class Node:
        __slots__ = ("lo", "hi", "label", "priority", "left", "right")

        def __init__(self, lo, hi, label):
            self.lo = lo
            self.hi = hi
            self.label = label
            self.priority = randbits(64)
            self.left = None
            self.right = None

    # All keys in a must precede all keys in b.
    def merge(a, b):
        if a is None:
            return b
        if b is None:
            return a
        if a.priority >= b.priority:
            a.right = merge(a.right, b)
            return a
        b.left = merge(a, b.left)
        return b

    # Split by run start: keys < x versus keys >= x.
    def split(t, x):
        if t is None:
            return None, None
        if t.lo < x:
            a, b = split(t.right, x)
            t.right = a
            return t, b
        a, b = split(t.left, x)
        t.left = b
        return a, t

    def first(t):
        while t.left is not None:
            t = t.left
        return t

    def last(t):
        while t.right is not None:
            t = t.right
        return t

    def pop_first(t):
        if t.left is None:
            return t.right
        t.left = pop_first(t.left)
        return t

    def pop_last(t):
        if t.right is None:
            return t.left
        t.right = pop_last(t.right)
        return t

    root = None
    run_count = 0
    totals = {}
    answer = []

    # Unlike split(), this also cuts a run that straddles x.
    # It does not change any painted positions or label totals.
    def cut(t, x):
        nonlocal run_count

        a, b = split(t, x)
        if a is not None:
            tail = last(a)
            if tail.hi > x:
                fragment = Node(x, tail.hi, tail.label)
                tail.hi = x
                b = merge(fragment, b)
                run_count += 1
        return a, b

    for op in ops:
        kind = op[0]

        if kind == "runs":
            answer.append(run_count)
            continue

        if kind == "total":
            answer.append(totals.get(op[1], 0))
            continue

        if kind == "at" or kind == "next_change":
            p = op[1]
            t = root
            predecessor = None
            successor = None

            while t is not None:
                if p < t.lo:
                    successor = t
                    t = t.left
                else:
                    predecessor = t
                    t = t.right

            if predecessor is not None and p < predecessor.hi:
                if kind == "at":
                    answer.append(predecessor.label)
                else:
                    answer.append(predecessor.hi)
            elif kind == "at":
                answer.append(None)
            else:
                answer.append(
                    successor.lo if successor is not None else None
                )
            continue

        # The remaining operations are paint and erase.
        l, r = op[1], op[2]
        if l >= r:
            answer.append(0)
            continue

        painting = kind == "paint"
        label = op[3] if painting else None

        left, rest = cut(root, l)
        middle, right = cut(rest, r)

        # Remove all covered runs and update their label totals.
        # A paint changes every covered position except those already
        # carrying its label. An erase changes only painted positions.
        changed = r - l if painting else 0
        stack = [middle] if middle is not None else []

        while stack:
            node = stack.pop()
            length = node.hi - node.lo

            totals[node.label] -= length
            run_count -= 1

            if painting:
                if node.label == label:
                    changed -= length
            else:
                changed += length

            if node.left is not None:
                stack.append(node.left)
            if node.right is not None:
                stack.append(node.right)

        if painting:
            totals[label] = totals.get(label, 0) + (r - l)
            lo, hi = l, r

            # Coalesce with matching adjacent runs.
            if left is not None:
                neighbor = last(left)
                if neighbor.hi == l and neighbor.label == label:
                    lo = neighbor.lo
                    left = pop_last(left)
                    run_count -= 1

            if right is not None:
                neighbor = first(right)
                if neighbor.lo == r and neighbor.label == label:
                    hi = neighbor.hi
                    right = pop_first(right)
                    run_count -= 1

            replacement = Node(lo, hi, label)
            root = merge(merge(left, replacement), right)
            run_count += 1
        else:
            root = merge(left, right)

        answer.append(changed)

    return answer

from collections import OrderedDict
from heapq import heapify, heappop, heappush


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    # Oldest use first; key -> (value, expires_at, version).
    store = OrderedDict()

    # (expires_at, unique_version, key).
    # Unique versions ensure heap comparisons never compare keys.
    expiry_heap = []

    out = []
    last_t = None

    for version, op in enumerate(ops):
        kind, t = op[0], op[1]

        if not isinstance(t, int):
            raise ValueError("timestamp must be an int")
        if last_t is not None and t < last_t:
            raise ValueError(
                "operations must have non-decreasing timestamps"
            )
        last_t = t

        # Expired entries must not exist for any operation, including size.
        while expiry_heap and expiry_heap[0][0] <= t:
            _, expired_version, key = heappop(expiry_heap)
            entry = store.get(key)
            if entry is not None and entry[2] == expired_version:
                del store[key]

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (
                not isinstance(ttl, int) or ttl < 1
            ):
                raise ValueError("ttl must be None or a positive int")

            expires_at = None if ttl is None else t + ttl

            if key not in store and len(store) >= capacity:
                store.popitem(last=False)

            store[key] = (value, expires_at, version)
            store.move_to_end(key)  # Every put is a use, including updates.

            if expires_at is not None:
                heappush(expiry_heap, (expires_at, version, key))

        elif kind == "get":
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

        # Rewrites and evictions leave stale heap records. Rebuild only
        # when enough have accumulated to amortize the rebuilding cost.
        if len(expiry_heap) > 2 * len(store) + 1024:
            expiry_heap = [
                (entry[1], entry[2], key)
                for key, entry in store.items()
                if entry[1] is not None
            ]
            heapify(expiry_heap)

    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue

        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue

        if ch == "#":
            end = src.find("\n", i)
            if end == -1:
                end = n
            # Leave the newline for the normal newline-handling branch.
            col += end - i
            i = end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1

            is_float = False

            # Consume a fraction only if it contains at least one digit.
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 2
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True

            # Probe the exponent without committing until its shape is valid.
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    k += 1
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True

            text = src[i:j]
            value = float(text) if is_float else int(text)
            tokens.append(("NUMBER", value, line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i + 1
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")

                c = src[j]
                if c == '"':
                    j += 1
                    break

                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue

                chars.append(c)
                j += 1

            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue

        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
